import { spawn, spawnSync } from "node:child_process";

import { validateBrowserFixtureRunId } from "./browser-fixture-run-id.mjs";

const POSTGRES_IMAGE = "postgres:17";
const POSTGRES_PASSWORD = "postgres";
const APP_ROLE_PASSWORD = "agent-outbox-browser-app-role";
const DATABASE_NAME = "agent_outbox_browser";
const APP_PORT = process.env.PORT;
const APP_BASE_URL = process.env.APP_BASE_URL;
const PUBLIC_APP_BASE_URL = process.env.PUBLIC_APP_BASE_URL;
// The run id is generated by playwright.config.ts and shared with globalTeardown
// so cleanup only ever removes this run's throwaway resources. Require it rather
// than self-generating: a divergent id would orphan resources the teardown
// cannot find.
const RAW_RUN_ID = process.env.AGENT_OUTBOX_BROWSER_RUN_ID;
if (!APP_PORT || !APP_BASE_URL || !PUBLIC_APP_BASE_URL || !RAW_RUN_ID) {
  throw new Error(
    "PORT, APP_BASE_URL, PUBLIC_APP_BASE_URL, and AGENT_OUTBOX_BROWSER_RUN_ID are required."
  );
}
const RUN_ID = validateBrowserFixtureRunId(RAW_RUN_ID);
const NETWORK_NAME = `agent-outbox-browser-${RUN_ID}`;
const CONTAINER_NAME = `agent-outbox-browser-postgres-${RUN_ID}`;
const HASH_SECRET = "agent-outbox-browser-fixture-hash-secret";
const BROWSER_FIXTURE_LABEL = "agent-outbox.browser-fixture=1";
const BROWSER_FIXTURE_RUN_LABEL = `agent-outbox.browser-fixture-run=${RUN_ID}`;

/** @type {import("node:child_process").ChildProcess | undefined} */
let nextProcess;
let cleanedUp = false;

process.once("SIGINT", () => stop(130));
process.once("SIGTERM", () => stop(143));
process.once("SIGHUP", () => stop(129));

try {
  run(
    "docker",
    [
      "network",
      "create",
      "--label",
      BROWSER_FIXTURE_LABEL,
      "--label",
      BROWSER_FIXTURE_RUN_LABEL,
      NETWORK_NAME
    ],
    {
      stdio: "ignore"
    }
  );
  run("docker", [
    "run",
    "-d",
    "--name",
    CONTAINER_NAME,
    "--label",
    BROWSER_FIXTURE_LABEL,
    "--label",
    BROWSER_FIXTURE_RUN_LABEL,
    "--network",
    NETWORK_NAME,
    "-e",
    `POSTGRES_DB=${DATABASE_NAME}`,
    "-e",
    "POSTGRES_USER=postgres",
    "-e",
    `POSTGRES_PASSWORD=${POSTGRES_PASSWORD}`,
    "-p",
    "127.0.0.1::5432",
    POSTGRES_IMAGE
  ]);
  waitForPostgres();

  const migrationUrl = `postgresql://postgres:${POSTGRES_PASSWORD}@${CONTAINER_NAME}:5432/${DATABASE_NAME}`;
  run("corepack", ["pnpm", "run", "migration:replay"], {
    env: {
      ...process.env,
      DATABASE_MIGRATION_URL: migrationUrl,
      FLYWAY_DOCKER_NETWORK: NETWORK_NAME
    }
  });
  run("docker", [
    "exec",
    "-e",
    `PGPASSWORD=${POSTGRES_PASSWORD}`,
    CONTAINER_NAME,
    "psql",
    "-U",
    "postgres",
    "-d",
    DATABASE_NAME,
    "-v",
    "ON_ERROR_STOP=1",
    "-c",
    `alter role agent_outbox_app with password '${APP_ROLE_PASSWORD}'`
  ]);

  const appDatabaseUrl = `postgresql://agent_outbox_app:${APP_ROLE_PASSWORD}@127.0.0.1:${postgresHostPort()}/${DATABASE_NAME}`;
  nextProcess = spawn(
    "corepack",
    ["pnpm", "exec", "next", "dev", "-p", APP_PORT],
    {
      env: {
        ...process.env,
        APP_ENV: "test",
        PORT: APP_PORT,
        APP_BASE_URL,
        PUBLIC_APP_BASE_URL,
        AGENT_OUTBOX_BROWSER_FIXTURE: "1",
        AGENT_OUTBOX_CONNECT_CLERK_FIXTURE: "1",
        DATABASE_APP_ROLE_URL: appDatabaseUrl,
        CALLER_KEY_HASH_SECRET: HASH_SECRET
      },
      stdio: "inherit"
    }
  );

  nextProcess.on("exit", (code, signal) => {
    cleanup();
    if (signal) {
      process.exit(signal === "SIGINT" ? 130 : 143);
      return;
    }
    process.exit(code);
  });
} catch (error) {
  cleanup();
  const failure = /** @type {Error} */ (error);
  console.error(failure.message);
  process.exit(1);
}

/**
 * @param {number} code
 */
function stop(code) {
  if (nextProcess && !nextProcess.killed) {
    nextProcess.kill("SIGTERM");
  }
  cleanup();
  process.exit(code);
}

function cleanup() {
  if (cleanedUp) {
    return;
  }
  cleanedUp = true;
  spawnSync("docker", ["rm", "-f", CONTAINER_NAME], { stdio: "ignore" });
  spawnSync("docker", ["network", "rm", NETWORK_NAME], { stdio: "ignore" });
}

function waitForPostgres() {
  for (let attempt = 0; attempt < 60; attempt += 1) {
    const result = spawnSync(
      "docker",
      [
        "exec",
        CONTAINER_NAME,
        "pg_isready",
        "-U",
        "postgres",
        "-d",
        DATABASE_NAME
      ],
      { stdio: "ignore" }
    );
    if (result.status === 0) {
      return;
    }
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 1_000);
  }
  throw new Error("Timed out waiting for browser test Postgres.");
}

function postgresHostPort() {
  const result = run("docker", ["port", CONTAINER_NAME, "5432/tcp"], {
    stdio: "pipe"
  });
  const output = String(result.stdout).trim();
  const match = output.match(/127\.0\.0\.1:(\d+)/);
  if (!match) {
    throw new Error("Could not determine browser test Postgres host port.");
  }
  return match[1];
}

/**
 * @param {string} command
 * @param {string[]} args
 * @param {import("node:child_process").SpawnSyncOptions} [options]
 * @returns {import("node:child_process").SpawnSyncReturns<string | Buffer>}
 */
function run(command, args, options = {}) {
  const result = spawnSync(command, args, {
    stdio: "inherit",
    ...options
  });
  if (result.error) {
    throw result.error;
  }
  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(" ")} failed.`);
  }
  return result;
}
